NAME = 'PohnOld: Old Public Domain Pohnpeian Bible'
BOOK = 'Revelation of John'

CHAPTERS = {
    1: {
        1: 'IET kasale pan Iesus Kristus, me Kot kotiki ong i, en kasale ong sapwilim a ladu kan meakai, me pan wiaui met koren. A kotin poronela sapwilim a tounlang, me a kotin kasaleki ong sapwilim a ladu Ioanes.',
        2: 'Me kadedeki masan en Kot, o kadede pan Iesus Kristus karos, me a kilanger.',
        3: 'Meid pai, me wadokedi o ir, me rong masan en kokop akan, o nekinekid me intingidier lole, pwe ansau me koren.',
        4: 'Iet ngai Ioanes, ong momodisou isu nan Asien: Mak o popol ong komail sang ren i, me kotikot met, o me kotikot mas o, o me pan kotido, o sang ren Ngen isu, me kotikot mon mol a,',
        5: 'O sang ren Iesus Kristus, me saunkadede melel, me meseni ren me iasadar sang ren me melar akan, o Kaun en nanmarki en sappa kan, me kotin kupura kitail o widen sang kitail dip atail ki nta,',
        6: 'O kotin wia kin kitail er samero ong Kot o Sam a. Lingan o manaman en mi re a kokolata! Amen.',
        7: 'Kilang, a kotido nan dapok kan, o mas karos pan kilang i, o irail me doke i, o kainok en sappa karos pan sangesangki i. Melel, Amen.',
        8: 'Ngai Alpa o Omeka, me Kaun Kot kotin masani, me kotikot eta, o me kotikot mas o, o me pan kotido, iei Dinkel amen.',
        9: 'Ngai Ioanes, ri omail, o omail warok ni kamekam, o ni wei, o ni atail auiaui Iesus, i lel dong nin dake o, me ad a Patmos, ki masan en Kot o kadede pan Iesus.',
        10: 'Ngen saraui kotikot po i ni ran en Kaun, i ap rongadar mur i ngil laud eu, me rasong ngil en koronete masani:',
        11: 'Me koe kilang, intingiedi nan puk eu, ap kadar wong momodisou isu en Episus, o Smirna, o Perkamus, o Tiatira, o Sardes, o Piladelpia, o Laodisea.',
        12: 'I ap soupei ong, en kilang ngil o, me kasoi ong ia. A i lao soupeilar, i kilang lamp kold isu.',
        13: 'O nan pung en lamp akan amen mia, me rasong Nain aramas, likauie kida likau eu, me leldi ong aluwilu a, o lukom kida ni maramar waiwai kold eu.',
        14: 'A kadokenmai o pit en peipei puetepueteta wun en sip puetepuet, o rasong sno, o silang i rasong umpul en kisiniai,',
        15: 'O aluwilu a rasong pras lingan likamata a lingaling nan kisiniai, o kapitie rasong ngirsok en pil toto.',
        16: 'O ni lim a pali maun usu isu mia, o sang nan silang i kodlas kong o au a riau u wei sang, o silang i rasong katipin, sirang kelailia.',
        17: 'A ni ai kilang i, i ap pupedi ni aluwilu a dueta mela amen. O a kotikidang po i lim a pali maun mamasani: Ender masak, ngai men mas o men mur.',
        18: 'O me maur men, o ai melar amen, ari kilang, i memaureta kokolata, o men kapir en mela o wasan mela mi re i.',
        19: 'Koe ari intingiedi meakan, me koe kilanger, o me mier, o me pan wiaui mur.',
        20: 'Wewe en usu isu, me koe kilanger nan pa i pali maun, o lamp kold isu. Usu isu, iei tounlang en momodisou isu, o lamp isu, iei momodisou isu.',
    },
    2: {
        1: 'INTING wong tounlang en momodisou en Episus: Iet masan en i, me kolekoleta ni lim a pali maun usu isu, o me kin weweid nan pung en lamp kold isu.',
        2: 'I asa om wiawia kan, o om dodok, o om dadaurata, o duen om sota kin mauki me sued akan, o koe kasaui ir adar, me akawanporon, a me so, ap diar ir ada me likam.',
        3: 'O koe kin kanongama ong o kadokeki mar ai, ap sota pangadar.',
        4: 'A iet me I suedeki re om: Koe muei sanger tapin om limpok.',
        5: 'Koe ari tamanda, me koe pupe wei sanger, o kalula, o kapwaiada wiawia en mas o; a ma so, I pan ko dong uk, kasau wei sang om lamp sang ni deu a, ma koe sota kalula.',
        6: 'A iet me koe kin wia, koe kin suedeki wiawia en nain Nikolaus akan, me I pil kin suedeki.',
        7: 'Me salong a mia, i en rong, me Ngen o masani ong momodisou kan! Me dadaurata, I pan ki ong i, en tungole sang tuka en kamaur, me mi nan paradis en Kot.',
        8: 'Inting wong tounlang en momodisou en Smirna: Iet masan en men mas o men mur, me melar ap mauredar.',
        9: 'I asa om kamekam, o om samama ari so, koe me kapwapwa, o lalaue en ir, me kin inda, dene irail men Sus, a kaidin irail men Sus, pwe pwin en Satan eu.',
        10: 'Koe der masak, me koe pan kalokolokki. Kilang, tewil o pan kaselong ong nan imateng akai komail, pwe komail en kasongesong, o komail pan kalokolok ran eisok. Dadaurata lel mela. I ap pan ki ong uk mar en maur soutuk.',
        11: 'Me salong a mia, i en rong, me Ngen o masani ong momodisou kan! Me dadaurata, sota pan kamekam kila mela kariau.',
        12: 'Inting wong tounlang en momodisou en Perkamus: Iet masan en me na kodlas kong o au riau mia:',
        13: 'I asa, wasa koe kauson ia, ni wasan mol en Satan, o koe kin podidi ong mar ai, o koe sota kamama kida om poson ia pil so ni ran oko, me Antipas, ai saunkadede melel men, kamekamelar nan pung omail, wasa Satan kin kauson ia.',
        14: 'A ekis tikitik ta, me I suedeki re om: Akai mi re om, me kin apwali lamalam en Pileam, me padaki ong Palak, en kasedi ong mon kadaudok en Israel kasapung par, ren tungole kisin man, me olu onger dikedik en ani kan, o ren nenek.',
        15: 'O pil akai mi re om, me pil apwali lamalam en nain Nikolaus akan.',
        16: 'Ari, kalula! A ma so, I pan madang wong uk o pepei ong irail ki kodlas en au ai.',
        17: 'Me salong a mia, i en rong, me Ngen o masani ong momodisou kan! Me dadaurata, I pan ki ong i mana sosansal, o I pan ki ong i takai puetepuet eu o nan takai mar kap intingidier, sota amen me dedeki, i eta, me pan ale.',
        18: 'Inting wong tounlang en momodisou en Tiatira: Iet masan en me Sapwilim en Kot, me silang i rasong umpul en kisiniai o aluwilu a rasong pras lingan.',
        19: 'I asa om wiawia kan, o om limpok, o om poson, o om papa, o om kanongama, o duen om wiawia men mur, me toto sang men mas.',
        20: 'A iet me I suedeki re om: Koe kin mueid ong li Isepel, me kin inda duen pein i, dene i saukop amen, me kin padaki o kotaue nai ladu kan, ren nenek, o ren tungole, me olu ong dikedik en ani.',
        21: 'O I ki ong i er ansau en kalula, a a kang kalukila a nenek.',
        22: 'Kilang, I pan kasedi i nan los, o irail me kin kamal re a, nan kamekam lapalap, ma re sota pan kalukila wiawia en Isepel akan.',
        23: 'O I pan kamekila na seri kan kamekam eu. Ari, momodisou karos pan asaki, me ngai i, me kin irerong nan mudilik o mongiong kan, o I pan ki ong amen amen komail iran omail wiawia kan.',
        24: 'A I indai ong komail tei kan, me mi Tiatira, karos me sota apwali lamalam wet, me so dedeki widing en Satan, duen ar lokaia. I sota pan ki ong komail eu katoutou pa’mail.',
        25: 'A me mi re omail, kolekoleta, I lao pwarado.',
        26: 'O me dadaurata o me kanekid ai wiawia kan lel imwi, i me I pan kasapwilada pon wei kan.',
        27: 'A pan kaun kida ir sokon mata, due dal en saupal kin ola kaualap, o due I pil aleer mana sang ren Sam ai,',
        28: 'I ap pan ki ong i usu ran.',
        29: 'Me salong a mia, i en rong me Ngen o masani ong momodisou kan!',
    },
    3: {
        1: 'INTING wong tounlang en momodisou en Sardes: Iet masan en me Ngen en Kot isu o usu isu mi re a: I asa om wiawia kan, o me mar en maur mi re om, a so, koe melar.',
        2: 'Pirida, katenge me lua, me nok mela, pwe I sota diaradar, me om wiawia kan unsokela ren ai Kot.',
        3: 'I me koe en tamanda, duen koe tungoler, o ronger, o kanekid, o kalula. Ma koe sota pan pirida, I pan pwarado due lipirap amen, o koe pan sasa auer, me I pan pwara dong uk.',
        4: 'A mar malaulau mi re om nan Sardes, me sota kapwelepwel lar ar likau kan, re pan alialu re i nan likau puetepuet, pwe re kon ong.',
        5: 'Me dadaurata, pan kapwad kida likau puetepuet, o I sota pan irise sang nan puk en maur mar a. O I pan kadede mar a mon Sam ai o mon na tounlang kan.',
        6: 'Me salong a mia en rong, me Ngen o masani ong momodisou kan!',
        7: 'Inting wong tounlang en momodisou en Piladelpia: Iet masan en me saraui, me melel, me men kapir en Dawid mi re a, me kin ritingida, o sota amen, me kak ritingidi, o me kin ritingidi, o sota amen, me kak ritingida.',
        8: 'I asa om wiawia kan. Kilang, I ki ong uk er wanim ritidar eu o sota amen, me kak ritingidi, pwe om kel me tikitik, o koe kin kanekid ai masan, o koe sota kamam kidar mar ai.',
        9: 'Kilang, I kanain kin uk akai, me udan pwin en Satan, kisan irail, me akasus, a so, re likam. Kilang, I pan kainong ir do, en pongi ni nä om, o ren asa, me I kin pok ong uk.',
        10: 'Aki om kanekid ai masan en kanongama, I pil pan kanekid uk ni auer en kasongesong, me pan udong toun sappa karos, en kasongesong irail, me kauson sappa.',
        11: 'I pan pwarado madang. Kolekol, me koe anekier, pwe sota amen en kulia sang mar om.',
        12: 'Me dadaurata, I pan wiaki i ur eu nan tanpas en ai Kot, o a solar pan pedoi sang kokolata. I pan inting po a mar en ai Kot, o ad en kanim en ai Kot, Ierusalem kap, me peidido sang ai Kot nanlang o mar ai kap.',
        13: 'Me salong a mia, en rong, me Ngen o masani ong momodisou kan!',
        14: 'Inting wong tounlang en momodisou en Laodisea: Iet masan en me maraneki Amen, me saunkadede lelapok melel, me tapin dodok en Kot.',
        15: 'I asa om wiawia kan, koe sota karakar o pil sota lamelamur. I men, koe en lamelamur de karakar!',
        16: 'Ari, koe me lou, a kaidin karakar de lamelamur, I ap pan mus kin uk wei sang nan au ai.',
        17: 'Pwe koe inda: Ngai kapwapwa, i anekier kapwa kan, o i sota kin anane meakot, ap sasa, me koe sakanekan, o so konekon, o samama, o maskun, o kiliso.',
        18: 'I panaui uk, koe en neti sang ia kold lingan, aki kisiniai, pwe koe en kapwapwala, o likau puetepuet, pwe koe en likauie uk, o kanamenok pan om kiliso der sansal, o wini en mas o, men elieliki mas om, en kilang wasa.',
        19: 'I kin kapung ong o kaloke karos, me I pokepoke. Koe nantiong kalula!',
        20: 'Kilang, I kin u pan wanim o letelet. Meamen pan rong ngil ai, ap ritingida wanim o, I pan pedelong re a, ap iang i mot ong ras saraui, o a iang ia.',
        21: 'Me dadaurata, I pan ki ong i, en iang, ia mondi pon mol ai, dueta ngai pil dadaurata, ap iang Sam ai mondi pon mol a.',
        22: 'Me salong a mia, i en rong, me Ngen o masani ong momodisou kan!',
    },
    4: {
        1: 'MURIN mepukat i kilanger kasansal eu: Kilang, wanim eu ritidar nanlang, o ngil, me i ronger mas, dueta koronete eu kasokasoi ong ia: Koda dong met! I pan kasale ong uk, me pan wiaui mur en mepukat.',
        2: 'Ngai pitipit katia Ngen. A kilang, mol eu mi nanlang, o amen kotidi pon mol o.',
        3: 'A sansal en me kotidi poa rasong takai Iaspis o Sardis o aia me liteui mol o, me sansal dueta takai smarakd.',
        4: 'O mol o kapilki pena mol rieisok paieu, o lapalap riek pamen kotikot poa, likau kida likau puetepuet o nin kida nin kold.',
        5: 'O sang ni mol o liol, o ngil akai, o nansapwe kai use wei sang, o lamp isu umpumpul mon mol o, iei Ngen isu en Kot.',
        6: 'O mon mol o dueta sed eu, me rasong klas o kristal, o nan warong en mol o, o impan mol o man maur pamen, me rok ki por en mas mo ar o mur ir.',
        7: 'Man en mas me rasong laien amen, o man kariamen rasong kau ol amen, o man kasilimen kar i rasong aramas, o man kapamen rasong manpir ikel.',
        8: 'O man maur pamen ko pa en pir wonu mi ren amen amen, me rokki por en mas ni kaila o lole, o re sota nenenla ni ran o ni pong, indinda: Me saraui, me saraui, me saraui, Kaun Kot, Kaun en meakaros, me kotikot mas, o me kotikot met, o me pan kotin pwarado.',
        9: 'Ari man maur oko, lao pan kalinganada, o kakaki, o danke i me kotidi pon mol o, me ieias soutuk,',
        10: 'Me lapalap riek pamen ap pan poridi ong i, me kotidi pon mol o, o re pan pongi i, me ieiasata kokolata, o re pan pwilikidi mar ar mon mol o, indada:',
        11: 'Komui Maing, at Kaun, o at Kot, me kon ong, en linganla, o kakala, o manaman, pwe ir me kotin kapikadar meakan karos o pweki kupur omui re mia kier o wiaui kidar.',
    },
    5: {
        1: 'O i kilanger nan lim pali maun, en me kotidi pon mol o, puk eu, intingidier lole o liki o katengeki pena men kateng isu.',
        2: 'O i kilang tounlang kelail amen, pepeidokki ngil laud: Is me kon ong pak pasang puk o, o lapwada a men kateng kan?',
        3: 'A sota amen, me mi nanlang de nin sappa, de pan sappa, me kak ong pak pasang puk, o udial i.',
        4: 'Ari, i ap sangesang kaualap, aki sota amen, me diarokadar, me kon ong, en pak pasang puk o, de udial i.',
        5: 'O amen ren me lapalap akan masani ong ia: Koe der sangesang! Kilang, Laien, me udan kainok en Iuda, tapin Dawid, me pwaidar ni a peipei, pwen kon ong, pak pasang puk o, o lapwa sang men kateng isu.',
        6: 'O i kilang nan warong en mol o nan pung en man pamen o nan pung en lapalap akan Sippul amen u due kamekamelar, me ose isu o por en mas a isu mia, iei Ngen en Kot isu me pakadaralang dol en sappa karos.',
        7: 'A kotido, ap kotiki sang puk o ni lim a maun en me kaipokedi pon mol o.',
        8: 'A ni a kotin aleer puk o, man maur pamen, o lapalap riek pamen poridi ong mon Sippul o. Amen amen re irail kolekol a arp o dal kold, me dir en potik en isis, iei kapakap en saraui kan.',
        9: 'Irail kauleki kaul kap pot indinda: Ir me kotin kon ong, kotikida puk o, o lapwada a men kateng ko, pwe komui kamatalar o neti ki ong Kot nt’ omui sang ni kainok karos, o lokaia karos, o men liki karos, o wei karos.',
        10: 'O kotin wia kin irail la wei eu ong atail Kot, pwen samero kan, o re pan nanmarki nin sappa.',
        11: 'O i kilanger o i ronger ngil en tounlang toto impan mol o, o man maur ko, o lapalap oko; irail me ngederenia nen nen o kid kid,',
        12: 'Irail indinda ni ngil laud: Sippul o me kamekamelar, me kon ong aineki manaman, o kapwa, o erpit, o kel, o kaka, o lingan, o pai kan.',
        13: 'Ir karusia nanlang, o sappa, o pan sappa, o pon madau, o aude pan arail karos, i ronger me re indinda: Me kotidi pon mol o, o Sippul en kapinganla, o kakala, o kalinganada o manaman kokolata.',
        14: 'Man maur pamen masani: Amen, O lapalap akan poridi ong pongi i.',
    },
    6: {
        1: 'I kilang ni en Sippul a lauad pasang eu ren kateng isu, o i ronger amen ren man pamen masanieki ngil me rasong nansapwe: Kodo!',
        2: 'I ap kilanger os puetepuet amen, o me mondi poa kasik katieu mi re a, o mar eu ko ong i, i ari koti wei, pwen kalokaloedi.',
        3: 'Ni a lauad pasang kateng kariau, i ap ronger man kariamen masanier: Kodo!',
        4: 'Amen os me waitata ap pwarado, a me mondi poa a muei ong i, en kawela muei mau nin sappa, o tou a kan pakamekam pena, a kodlas kalaimun me pangalang i.',
        5: 'Ni a lauad pasang kateng kasilu, i ronger man kasilimen masani: Kodo! I ap kilanger os tontol amen, o me mondi poa, men tenok mi ni lim a.',
        6: 'O i ronger ngil eu nan pung en man pamen indinda: Song en wit eu denar eu, o song en korn silu denar eu, a le o wain der kawela!',
        7: 'A ni a lauad pasang kateng kapaieu, i ronger ngil en man kapamen masani: Kodo!',
        8: 'I ap kilanger os pasas, o me mondi poa, mar a Mela, o wasan mela me idauen i. A kapi ong i en kaunda pakis eu en sappa, en kamekila kodlas, o isesol, o mela, o ren man laualo en sappa kan.',
        9: 'A ni a lauad pasang kateng kalimau, i kilanger pan pei saraui ngen en me kamekila masan en Kot, o ar kadede, me re wia.',
        10: 'Irail likelikwirki ngil laud indinda: Arai da, Maing, Kaun saraui o melel, komui so kadeikada o iki kin nt’ at ong irail, me kauson sappa?',
        11: 'Likau puetepuet me pangalang irail karos, o a kotin masani ong irail, ren moleilei mas ekis, a lao iang ar o ri ar akan unsokelar, me pan kamekamela dueta pein irail.',
        12: 'O i kilanger ni a lauad pasang kateng kawonu, rerer en sappa lapalap ap wiaui, katipin rotala dueta likau tontol, wunen eu o maram waitatala dueta nta.',
        13: 'O usu en lang akan pupedi ong sappa, due tuka pik pot kasedi wa kan me pul, ni a tuälok ki ang ma,',
        14: 'O lang kasaula dueta kisin likau ni a limlim pena, o nana karos o dake karos torak sang deu ar,',
        15: 'O nanmarki en sappa kan, o monsap, o saumas akan, o kapwapwa kan, o me kelail, o ladu kan karos, o maio kan rukila nan por o pan paip en nana kan.',
        16: 'Ap indang nana o paip akan: Pupedi po at o pwain kidi sang mon silang en i me kotidi pon mol o, o sang ni ongiong en Sippul.',
        17: 'Pwe a leler ran lapalap en a ongiong; o is me pan kak pwaida?',
    },
    7: {
        1: 'MURIN met i kilanger tounlang pamen uda ni kaim en sappa paieu kolekol ang paieu en sappa, pwe ang ender ipuip dong sappa, de pon sed, de nin tuka pot.',
        2: 'O i kilanger amen tounlang pwarada sang ni mas en lang, kilelekidi kilel en Kot ieias. A likwirki ngil laud ong tounlang pamen, me udan kawela sap o sed,',
        3: 'Indinda: Der kawela sappa de madau, de tuka kan, a lao kileledier ladu en at Kot akan ni tam ar!',
        4: 'Ngai ari rongadar arail wadok me kileledier me lop panen pakid sang nin kainok en Israel akan karos.',
        5: 'Sang ni kainok en Iuda nen riakid kileledier, sang ni kainok en Rupen nen riakid, sang ni kainok en Kat nen riakid,',
        6: 'Sang ni kainok en Aser nen riakid, sang ni kainok en Naptali nen riakid, sang ni kainok en Manase nen riakid,',
        7: 'Sang ni kainok en Simeon nen riakid, sang ni kainok en Lewi nen riakid, sang ni kainok en Isasar nen riakid,',
        8: 'Sang ni kainok en Sepulon nen riakid, sang ni kainok en Iosep nen riakid, sang ni kainok en Peniamin nen riakid.',
        9: 'Murin mepukat i kilanger pokon kalaimunia, sota amen me kak wadokedi sang ni wei karos, o kainok karos, o men liki karos, o lokaia karos, o mon mol o, o mon Sippul likau kida likau puetepuet o paini ni lim ar,',
        10: 'O re ngil laudeda indinda: Kot kamaur pat, me kaipokedi pon mol o o Sippul.',
        11: 'Tounlang karos u kapil pena mol o, o lapalap akan, o man pamen, irail pori kidi mas ar mon mol o, pongi Kot,',
        12: 'Indinda: Amen! Pai, o lingan, o erpit, o danke, o wau, o roson, o manaman ong atail Kot kokolata! Amen.',
        13: 'O amen ren me lapalap akan sapeng masani ong ia: Is irail me likau kida likau puetepuet, o irail kodo sang ia?',
        14: 'I ap potoan ong i: Maing, komui mangier. A sapeng ia: Ir me pwaida sang ni kaankamekam, o re lope ar likau, o kapwad kida ntan Sippul.',
        15: 'I me re mikier mon mol en Kot, o papa i ni ran o ni pong nan sapwilim a im en kaudok, o me kaipokedi pon mol o, pan apapwali irail.',
        16: 'Irail solar pan men manga potopoteta, o solar men nim pilada, o katipin solar pan daker ir, de eu song en karakar pan lel.',
        17: 'Pwe Sippul ni warong en mol o pan kotin wia sile parail, o a pan kalua ir wong ni pil en maur, o Kot pan lim wei sang pil en mas arail.',
    },
    8: {
        1: 'NI a lauad pasang kateng kaisu, kaporamen wiaui nanlang alep en auer.',
        2: 'O i kilanger tounlang isimen, me uda mon Kot, o koronete isu pangalang irail.',
        3: 'Amen tounlang me kotido u pon pei saraui, dal kold, men isik potik, mi re a; potik isis toto pangalang re a, pwen kamanada kapakap en saulang kan, me mi mon mol o.',
        4: 'Ad in isik iangaki kapakap en me saraui kan adidalang Kot sang ni lim en tounlang o.',
        5: 'Tounlang ari aleda dal en potik o, ap aude kida kisiniai en pei saraui, ap kasedi ong sappa; ari, nansapwe, o ngil akan, o liol, o rerer en sappa wiauier.',
        6: 'A tounlang isimen, me ar koronete isu mia, kaonopadang pepeuk.',
        7: 'Men mas pepeuk koronete, akel o kisiniai iangaki nta ap wiauier o pisikindi lang sappa; a silekis eu en sappa rongala, o silekis eu en tuka rongala, o rä karos rongala.',
        8: 'O tounlang kariamen pepeuk koronete ap likamata nana lapalap eu isisiki kisiniai ap pisikindi lang madau; a silekis eu en madau ap wialar nta.',
        9: 'O silekis eu en tou a maur melar nan sed, o silekis eu en sop akan olar.',
        10: 'A tounlang kasilimen pepeuk koronete, usu lapalap ap pupedi sang nanlang likamata ser umpumpul eu pupedi pon silekis eu en pilap akan o utun pil akan.',
        11: 'Ad en usu o Sadik; silekis eu en pil akan ap sadikalar, o aramas toto mekilar pil aki ar sadik.',
        12: 'A tounlang kapamen pepeuk koronete, silekis eu en katipin, o silekis eu en maram, o silekis eu en usu kan ap olar. Silekis eu ari rotongala o ran solar marain ni a silekis eu o pil dueta pong.',
        13: 'O i kilanger o ronger ikel amen pipir nan warong en lang, indindaki ngil laud: Apwal, apwal, apwal ong irail, me kaukausonta sappa, pweki ngil en koronete en tounlang silimen, me pan pepeuk mur.',
    },
    9: {
        1: 'TOUNLANG kalimen pepeuk koronete, i ap kilang usu en lang eu, me pupedi ong sappa, o ki en wasa lol me pangalang i.',
        2: 'A ritingida au en wasa lol, adiniai ap adida sang nan wasa lol o, dueta adiniai en um kalaimun, o katipin o pan lang rotorotala, pweki adiniai en wasa lol.',
        3: 'O mansiek kan me pwarado sang nan adiniai, rap paraparalang sappa, o manaman pangalang irail dueta skorpion en sappa.',
        4: 'A masani ong irail, ren der kawela rä nan sap, de tuka ta tontol, o pil so tuka laud, a aramas akan ta, me so kileleki kilel en Kot ni tam arail.',
        5: 'A so muei ong irail, en kame ir ala, a ren kaloke irail saunipong limau; o ar wairok me laud dueta lip en skorpion, ma a pan ke aramas amen.',
        6: 'Ni ran puko aramas pan rapaki mela, ap sota pan diarada; o re pan inong iong mela, a mela pan tang wei sang irail.',
        7: 'Mom en mansiek kan dueta os, me onoper mauin, o pon mong arail meakot, me rasong mar kold, o mas ar dueta mas en aramas.',
        8: 'Pit en mong arail rasong pit en mong en li, o ngi arail dueta ngi en laien.',
        9: 'Pere me mi re’rail dueta pere mata, o ngirsok en pa arail dueta ngirsok en war, me os toto me tangaki wong nan mauin.',
        10: 'O iki’rail dueta skorpion, o ose ar mia, o re keleki iki’rail, o re kin kame aramas saunipong limau.',
        11: 'O arail nanmarki ani en kadar en wasa lol, ad a ni lokaia en Ipru Apadon, a ad a ni lokaia en Krik Apolion.',
        12: 'Ari, tapin apwal akan daulier, a kilang, pil riau pan pwarado mur.',
        13: 'Tounlang kawonemen pepeuk koronete, i ap rong ngil eu, me tapida sang nan ose paieu en pei saraui, me mi mon Kot.',
        14: 'Amen indang tounlang kawonemen, me a koronete mia: Lapwada tounlang pamen, me salidier ni kailan pilap Oiprat.',
        15: 'Ari, tounlang pamen oko sapdokalar, me onoper ong auer, o ran, o saunipong, o par, pwe ren kamela silekis eu en aramas akan.',
        16: 'Wadawad en tounpei, me dake os riasap; o i ronger duen toto ar.',
        17: 'Iduen ai kilanger os akan ni kasansal o, o irail, me mod po arail, pere pras arail dueta kisiniai, me meimei o dueta swepel, o mong en os oko dueta mong en laien; o sang ni au arail kisiniai, o ad, o swepel kin adewei.',
        18: 'Kariapa silu pukat silekis eu en aramas akan, me kamekilar, kisiniai, o ad, o swepel, me adewei sang ni au arail.',
        19: 'Kelail en os akan mi nan au ar, o ni padaik arail, pwe padaik arail dueta serpent kan, o mong ar mia, o re kamekamki ir padaik ar.',
        20: 'A luan aramas akan, me so kamekilar kamekam pukat, kang kaluki wiawia en pa arail, pwe ender pongi ong tewil akan o dikedik en ani, me wiaki kold, o silper, o pras, o takai, o tuka, me so kak ngar wasa, o so rong wasa, o so alialu.',
        21: 'Irail sota kaluki ar kamela, o ar wun ani, o ar nenek, o ar lipirap.',
    },
    10: {
        1: 'O I kilanger amen tounlang kelail, me kotidido sang nanlang, me likauida dapok eu, o aia mi pon kadokenmai, o silang i dueta katipin, o aluwilu a dueta ur kisiniai.',
        2: 'Ni lim a kisin puk mia, me papak pasang, o aluwilu a pali maun sokedi pon madau, a pali maing pon sappa,',
        3: 'O a kotin molipe kida ngil laud, due laien amen ni a weriwer, o ni a molipeer, nansapwe isu ap ngiringir.',
        4: 'A nansapwe isu ngiringiridar, i men inting, i ap rong ngil eu sang nanlang masani: Katenge meakan, me nansapwe isu masanier, der inting ir edi!',
        5: 'Tounlang o, me i kilanger u pon madau o sappa, puekada lim a pali maun,',
        6: 'Ap kauki i, me ieiasata soutuk, me kotin kapikadar lang o meakan mi lole, o sappa o meakan mi lole, o madau o meakan mi lole, me solar pan ansau.',
        7: 'A ni dokan ngil en tounlang kaisimen ni a pan pepeuk, iei ansau karir pan Kot kaunsokalar, duen a kotin kokop ong sapwilim a ladu saukop akan rongamau o.',
        8: 'Ngil o, me i ronger sang nanlang, a pil masani ong ia er masani: U ko wei, aleda kisin puk, me papak pasanger, ni lim en tounlang, me uda pon madau o pon sappa!',
        9: 'Ari, i ap ko wong tounlang o, potoan ong i, en ki dong ia kisin puk o. A masani ong ia: Ale, ap kangala, a pan kasadikala kaped om, a ni au om a pan iau dueta onik.',
        10: 'I ap aleer kisin puk o sang ni lim en tounlang ap kangalar. Ari, nan au i me iau due onik, a murin i kanger, kaped i ap sadikalar.',
        11: 'A masani ong ia: Koe nok pil kokopada iran men liki kan, o aramas akan, o lokaia kan, o nanmarki toto.',
    },
    11: {
        1: 'O MEN song dueta sokon pot pang dong ia. Amen inda: Uda, song im en kaudok en Kot, o pei saraui, o irail me kaukaudok lole!',
        2: 'A kapil penan im en kaudok kasela liki o der song, pwe a pangalanger men liki kan o kanim saraui re pan kakaue saunipong paeisok riau.',
        3: 'O I pan kamanada nai saunkadede riamen, o ira pan kokop wei ran kid riepuki woneisok, likau kida likau tol.',
        4: 'Ira tuka olip riapot o lamp riau, me mimi mon Kaun en sappa.',
        5: 'Ma amen men kame ira, kisiniai pan lus wei sang nan au ara, ap karongala naira imwintiti kan. O ma amen men kame ira, a pan kamela.',
        6: 'Ira manaman ong en pinala lang, pwe ede katau arain ara kokopada, o ira kaun en pil, ira kak kawuk ong nta pil akan o kame ki sappa song en kamekam karos, due ira inong iong.',
        7: 'Ira lao kanikiela ara kadede, man o, me pan pwarada sang wasa lol, pan pei ong ira, kaloe ira di, kame ira la.',
        8: 'O kalep ara pan wonon nani al en kanim lapalap, me ad a ni karaseras Sodom o Äkipten, wasa ar Kaun pil kalopular.',
        9: 'Ari, me toto sang ren men liki kan, o kainok, o lokaia, o aramas akan pan kilang kalep ara ran silu alep, o irail sota pan mueid ong, me ara kalep pan saredi nan sousou.',
        10: 'O irail, me kaukauson sappa, kaneket kin ira o pereperen, re pan pakisakis pena, pwe saukop riamen et kin kaloke irail, me kaukauson sappa.',
        11: 'A murin ran silu alep maur sang ren Kot pil til wong lol ara, rap u ni nä ara, a irail, me kilang ira, masakada kaualap.',
        12: 'O i ronger ngil laud eu sang lang mamasani ong ira: Koma koda dong met! Ira ap kokidalang dapok, o imwintiti ara kilang ira.',
        13: 'Ni auer ota sappa rerer kaualap, eisokkis eu en kanim olar ni rerer, o mar isekid en aramas mekilar, me tei kan masakalar, rap landar Kot en lang.',
        14: 'Kamekam kariau wiauier. Kilang kamekam kasilu me pan pitipit wiaui.',
        15: 'Tounlang kaisimen pepeuk koronete. Ngil laud ap wiauier nanlang indinda: Wein sappa id wialar wein atail Kaun o sapwilim a Kristus. A pan kotin kaunda kokolata.',
        16: 'A lapalap riek pamen, me ariri Kot pon mol arail, rap pupedi ni silang ir pongi Kot masani:',
        17: 'Se danke komui, Maing Kot, Kaun en meakaros, me kotikot metet, o me kotikot mas o, pwe re kotin aleer ar manaman lapalap, o kotin Nanmarki lar.',
        18: 'O wei kan makaradar, a ar ongiong leler, o a leler ansaun melar akan pakadeik, o a leler ansau en katingi sapwilim omui ladu saukop akan o saraui kan; irail, me lomwineki mar ar, tikitik kan o lapalap akan, o en kawe irail, me kin kawela sappa.',
        19: 'Im en kaudok en Kot, mi nanlang, ritidar, o kopa en inau pingngar nan im en kaudok o; a liol, o ngil akan, o nansapwe kan, o rerer en sappa, o akel lapalap wiauiedar.',
    },
    12: {
        1: 'KILEL lapalap eu pingngar nanlang: Li amen linganeki katipin, o maram pan nä a, o a mareda usu eisokriau.',
        2: 'A liseanlar, a weriwer en naitik, waiwairok en sapedokla sang.',
        3: 'Pil eu kilel pingngar nanlang: Kilang, drake lapalap waitata, monga me isu, o salong a eisok, o mar isu pon mong a.',
        4: 'O a padaik urakiwei silekis eu en usu en lang, ap sipedi ir ong sappa. O drake uda mon li o, me pan naitik, pwe lao a naitiker, a en katalala na seri.',
        5: 'Ari, a naitikadar na seri ol, me pan kaun kida kainok karos sokon mata; ari, na seri peukadalang Kot ong mol a,',
        6: 'Li o tang wong sap tan, me deu a onoper ren Kot, iei wasa o re kin kamanga i ran kid riepuki woneisok.',
        7: 'Mauin pwaidar nanlang. Mikael o sapwilim a tounlang kan mauini ong drake o, o drake o na kan mauini ong.',
        8: 'A re so pwaida o solar deu ar nanlang.',
        9: 'O drake lapalap pisikindila, iei serpent, me ad a Tewil o Satan, katiamau pan sappa karos, i me pisikindi lang sappa, o na kan iang i pisikindila.',
        10: 'O i ronger ngil lapalap eu nanlang indinda: Metet me pwaidar kamauapan, o wiauipan, o wei en atail Kot, o manaman en sapwilim a Kristus, pwe karaune pan ri atail pisikindila, me kin karaun kin irail mon Kot ni ran o ni pong.',
        11: 'A re kaloedi i aki ntan Sippul o, o pweki masan en ar kadededa lamalam; o re so pok ong maur arail lao lel ong mela.',
        12: 'I me lang en perenda, o komail me kaukauson lole! A mesued ong sappa o madau, pwe tewil me kodilang komail, makarada kaualap, pwe a asa, me a ansau me motomot.',
        13: 'Drake o ni a kilanger, me a pisikindier sappa, a kansore li, me naitiker seri ol.',
        14: 'Pa riau en manpir ikel lapalap, me pangalang li o, pwen pirlang deu a nan sap tan, wasa o a pan nekinek ia ansau eu, o ansau kan, o alep en ansau, doo sang mas en serpent o, wasa a pan kamanga ia.',
        15: 'A serpent o kusepoke wei sang nan au a ong li o pil, dueta pilap pot, pwen kapwiliki wei li o.',
        16: 'A sappa puporki li o, o sappa sara pasang au a nimala pilap o, me drake o kusepoke wei sang nan au a.',
        17: 'O drake makar pan li o, ap kola, en mauini ong luan kadaudok a, me kin nekidala kusoned en Kot akan o koledi kadede pan Iesus. A ngai uda pon pik en oror.',
    },
    13: {
        1: 'I AP kasinenda pon pik en oror o kilanger man amen pwaradar sang nan madau, me a ose ek o monga isu mia, o mar eisok mier pon ose kan, o ni monga ad en lalaue kan.',
        2: 'Man o, me i kilanger, dueta parder amen, o nä a dueta nä en pär amen, o au a rasong au en laien. O drake ki ong i a kelail, o mol a, o a manaman lapalap.',
        3: 'O i kilanger monga eu dueta kamekamelar, ari so, a kamekam motier, a toun sappa karos puriamuiki man o.',
        4: 'Irail ari pongi ong drake, pwe a kapieki man o a kelail, o re pongi ong man o indinda: Is me rasong man o? O is me pan kak mauini ong i?',
        5: 'O a pang ong i au en suai lapalap, o en lalau eu, o a pang ong i, en mimieta saungipong paeisok riau.',
        6: 'Ari, a sara pasang au a, en lalaue Kot, en laue mar a o tanpas a saraui, o irail me kotikot nanlang.',
        7: 'O a kapieki i, en mauini ong saraui kan o kaloe irail edi; o a kapieki i, en kaunda wei karos, o men liki kan, o lokaia, o kainok kan.',
        8: 'O irail karos, me kaukauson sappa, pan pongi ong i karos, me mar arail sota intingidier nan puk en maur en Sippul, me kamekamelar sang nin tapin sappa.',
        9: 'Meamen salong a mia, en rong.',
        10: 'Ma amen pan kaloedi, nan pein i pan lodila; o ma amen pan kamekila, kodlas, nan a pan kamekila kodlas. Nan iet en saraui kan ar konongama o ar poson.',
        11: 'O i kilanger, amen man pwarado sang nan pwel, ose riau mia, rasong sippul amen, o a kasoi dueta drake amen.',
        12: 'O man o kin wia manaman akan karos dueta men mas mon por en mas a. O a wiada, me toun sappa en pongi ong man o, me kelailadar sang a kamekam.',
        13: 'A wiadar kilel lapalap, kamoredi sang lang kisiniai pon sappa mon aramas akan.',
        14: 'O a kotaue kin ir, me kaukauson sappa a kilel akan, me kapi ong i, en wiada mon man o, indai ong irail, me kausonta sappa, ren wiai ong man o, me a lop en kodlas mier, ap mauredar, dikedik eu.',
        15: 'O a kapi ong i, en kamaureda dikedik en man o, pwe dikedik en man o en pil lokaia, o en wiai ong irail, me kang pongi dikedik en man, en kamekamela.',
        16: 'O wiai ong karos, me tik o me lap akan, o kapwapwa kan, o samama kan, o me maio, o ladu kan, ren wia kilel eu ni pa ar pali maun de ni tam ar.',
        17: 'Pwe sota amen en kak net de netikila, pwe ir eta, me kileledier, kilelekidi mar en man de wad en mar a.',
        18: 'Iet lolekong. Me lolekong kan en wadokdi mar en man o, pwe a rasong wad en aramas amen; iet a wad: Wonepuki woneisok wonu.',
    },
    14: {
        1: 'O I kilanger Sippul o kotikot pon dol en Sion o me iang i lop panen pakid, o mar a o mar en Sam a intingidier ni tam ar.',
        2: 'O i ronger ngil eu sang nanlang dueta pungupung en pil toto o dueta ngirngir lapalap en nansapwe; ngil o, me i rongadar, dueta ngil en saunkaul pikipikir ar arp akan.',
        3: 'Irail kauleki kaul kap pot mon mol o, o mon man pamen o lapalap akan; o sota amen me kak koledi kaul o, irail lop panen pakid eta, irail me net sapal sang nin sappa.',
        4: 'Iei irail, me so samin kila li, pwe irail me makelekel. Iei irail me idedauen Sippul o, wasa a kin kotila ia. Mepukat net sapal sang ren aramas akan, me meseni ong Kot o Sippul.',
        5: 'O nan au ar sota likam me diarokadar, nan sota ar samin.',
        6: 'O i kilanger amen tounlang, pipir ni warong en lang, rongamau soutuk mi re a, pwen padaki ong irail, me kauson sappa, o ong wei karos, o kainok karos, o lokaia o aramas akan.',
        7: 'A masani ki ngil laud: Landa Kot, o waui i, pwe auer en a pan kotin kadeikada me pwarer; o pongi i, me kotin wiadar lang, o sappa, o madau, o utun pil akan.',
        8: 'O amen tounlang, kariamen, idauen i masani: A rongkilar, a rongkilar, Papilon lapalap, me kare ong kainok karos kamekam, aki ar nenek re a!',
        9: 'O amen tounlang, kasilimen, me idauen ir katitiki ngil laud: Ma amen pongi man o kilel en man, o ale kilel ni tam a o ni pa a,',
        10: 'A pan tungole en Kot a ongiong, me wiauier sokadolepa dal en ongiong en Kot, o a pan kalokeki kisiniai o swepel mon tounlang saraui kan o mon Sippul o.',
        11: 'O adiniai en ar lokolok peipeidala potopoteta, re so moleilei ni ran de ni pong, irail me pongi man o o a kilel, o irail me kilelekidar mar a.',
        12: 'Iet en saraui kan ar kanongama, me kin nekinekid kusoned en Kot akan o poson ong Iesus.',
        13: 'O i rong ngil eu sang lang masani: Intingiedi: Meid pai irail me mela ren Kaun o, met o kokolata! Iei, Ngen o me kotin masani, irail en moleilei sang ar wiawia kan, pwe ar wiawia kan iang irail.',
        14: 'O i kilanger dapok puetepuet eu, o Amen kotikot pon dapok o, me rasong Nain aramas, marakier mar kold, o ni lim a naip kong apot.',
        15: 'O amen tounlang pedoi wei sang nan im en kaudok, ekekerki ngil laud ong i, me kotidi pon dapok o: Komui kadar om naip paledi, pwe a leler auer en paledi, pwe rak en sappa mater kaualap!',
        16: 'Me kotidi pon dapok kasadi sappa a naip, rak kiri sang sappa.',
        17: 'O amen tounlang pedoi wei sang nan im en kaudok, me mi nanlang, pil naip kong apot mi re a.',
        18: 'O amen tounlang me pwarado sang impan pei saraui, me kin kakaun kisiniai, likwir ong i, me a naip kong mia, masani: Paledi! Tolunga sang wan wain en sappa, pwe wa me matier.',
        19: 'Ari, tounlang o paleki sappa naip, o tolung sang wan wain en sappa, o kasedi ong nan kopa laud en ongiong en Kot eu.',
        20: 'Irail tiakedi nan kopa en wain likin kanim, a nta kusewei sang nan kopa o lel ong sal en os, lel lang stadien kid wonepuki.',
    },
    15: {
        1: 'O I kilanger pil kilel eu nanlang, me lap o kalom: Tounlang isimen, a kalokolok isu mi re’rail, pwe ongiong en Kot kaimwisokki ir la.',
        2: 'O i kilanger sed klas eu, me doleki kisiniai o irail me kaloedi man o dikedik en man, o wadawad en mar a, uda ni kailan sed o, o arp en Kot mi re’rail,',
        3: 'O irail kauleki kaul en Moses ladu en Kot amen, o kaul en Sippul indinda: Omui wiawia kan me lapalap o kalom. Maing Kot, me pung o melel omui wiawia kan, komui Nanmarki en wei kan, Kaun en meakaros.',
        4: 'Is me so pan landa komui, Maing, o wauneki mar omui? Pwe komui ta me saraui, pwe wei karos pan pwarado pongi komui, pwe omui wiawia pung me sansaleda.',
        5: 'Murin mepukat i kilanger nan im en kaudok kadedepa mi nanlang me ritida.',
        6: 'O tounlang isimen pedoi wei sang nan im en kaudok kalokolok isu re’rail, kapwateki likau min o puetepuet, o ir piraki ni pan ati waiwai kold.',
        7: 'O amen ren man pamen pangalang tounlang isimen dal kold isu, direki ongiong en Kot, me ieiasata soutuk.',
        8: 'O im en kaudok me topkila adiniai tapida sang lingan en Kot o a manaman; o sota amen me kak pedelong ong nan im en kaudok o lao kalokolok isu en tounlang isimen wiauier.',
    },
    16: {
        1: 'O I ronger ngil laud eu sang nan im en kaudok o, mamasani ong tounlang isimen: Komail kowei, wudokedi ong sappa dal isu, me audekier ongiong en Kot.',
        2: 'Men mas ap kotiwei wudokila ong sappa a dal, ap wiala kins sued ong aramas akan, me kilelekidi kilel en man o, o me pongi a kilel.',
        3: 'O kariamen wudokila a dal ong nan madau ap wiala nta due nt’ en melar amen, ari me maur karos nan madau ap melar.',
        4: 'O kasilimen wudokila a dal pon pilap o utun pil akan, rap ntalar.',
        5: 'I ronger tounlang en pil akan masani: Komui me pung, me kotikot, o me kotikot mas, me saraui, pwe komui kadeikada due met.',
        6: 'Pwe irail kieledier ntan me saraui o saukop akan, ari, kom kotin katungole kin ir nta; ari, me mau ong irail.',
        7: 'I ronger me pei saraui o masani: Ei, Maing Kot, Kaun en meakaros, melel o me pung omui kadeik kan.',
        8: 'A kapamen wudokila a dal pon katipin, a kapi ong i, en isiki kisiniai aramas akan.',
        9: 'Ari, aramas rongkila karakar kaualap, o re lalaue mar en Kot, me Kaun pan kamekam pukat; a re sota kalukila, pwen wauneki i.',
        10: 'O tounlang kalimen wudokila a dal pon mol en man o; ari a wei rotorotala; o re ke pasang lo arail pweki motakan madak.',
        11: 'O irail lalaue Kot en lang, aki ar madak o ar kins akan, o re sota kalukila ar wiawia kan.',
        12: 'O tounlang kawonemen wudokila a dal pon pilap Oiprat, a pil ap ngalengaledi, pwen kaonopada al mon nanmarki, me kotido sang ni pali mas en lang.',
        13: 'O i kilanger, me sang nan au en drake, o sang nan au en man o, o sang nan au en saukop likam ngen samin silu dueta pros kai koda sang.',
        14: 'Ir ngen en tewil kai, wiawia kilel kai, me kin pwaralang nanmarki en sappa kan, en kapokon ir penang mauin en ran lapalap en Kot manaman.',
        15: 'Kilang, I pwarado dueta lipirap amen; meid pai, me kin masamasan, nekinekid a likau kan, pwe a de kilisola, rap kilang a kanamenok.',
        16: 'O re kapokon ir penang wasa, me ad a ni lokaia en Ipru Armakedon.',
        17: 'O tounlang kaisimen wudokila a dal nin wäwä, ngil laud ap pwaradar sang im en kaudok nanlang, sang ni mol o mamasani: A wiauier.',
        18: 'Ari, liol o ngil kai o nansapwe wiauier, o sappa rerer kaualap, sota due sang tapin aramas mi sappa, pwe me lapalap o mulatok.',
        19: 'Ari, kanim lapalap pal pasang wiala silekis silu, o kanim en sap akan rongk pasang, o Kot kotin tamanda kanim Papilon, pwen kotiki ong i dal en wain en a ongiong lapalap.',
        20: 'O dake karos mokid wei sang o nana kan solar sansal.',
        21: 'O akel lapalap, toutouki paun epuki, me moredi sang lang lel aramas akan, o aramas lalaue Kot pweki kamekam akel, pwe iei kamekam me lapalapia.',
    },
    17: {
        1: 'TOUNLANG amen, kisan isimen me ar dal isu mia, pwara do, masani ong ia: Kodo, i pan kasale ong uk en li sued, me kaunda pil toto, a pan kalokolok.',
        2: 'Me nanmarki en sappa kan nenekier, o me kaukauson sappa pweipweikier wain en a nenek.',
        3: 'Ari, a uke ia lang nan sap tan ren ngen. I ap kilanger li amen, mondi pon man waitata amen, ad a laue toto mia, monga isu o a ose eisok mia.',
        4: 'Li o likau kida likau tontol o waitata, o kapwat kida kold o takai kasampwal, o manaman kai, o ni pa a dal kold eu mia, me dir kila me samin o me saut en a nenek.',
        5: 'O ni tam a mar eu intingidier, iet: Okiok pot, Papilon lapalap in en me nenek kan o saut akan en sappa.',
        6: 'O i kilang li o a pweipweiki nt’ en saraui kan o nt’ en saunkadede en Iesus akan. Ari, ni ai kilanger i, i ap puriamui kaualap.',
        7: 'A tounlang o masani ong ia: Menda koe waponki? I pan kasale ong uk karasepan om waponki li o, o man o, o me a kin dake, me a monga isu o a ose eisok mia.',
        8: 'Man o, me koe kilanger, a mia mas ap soer mia, a nok pwaradado sang wasa lol, ap pan kolang wasan kamekam; o irail, me kaukauson sappa, pan wapon ki irail, me mar arail so intingidier nan puk en maur sang nin tapin sappa, ni ar kilang man o, due a mier mas, ap soer mia, ap nok pwarado.',
        9: 'Ari, iet lolekong: Monga isu rasong nana isu, me li o mondi poa.',
        10: 'O irail nanmarki isimen. Limen nikilar, me ta men mia, a amen kaikenta pwarado, a a lao pwarado, a pan sapwilada ansau kis.',
        11: 'A man o men mas, ap soer mia, i kawalemen, kisan isimen, ap pan kalokolok.',
        12: 'A ose eisok, me koe kilanger, rasong nanmarki ek, me kaikenta ar wei, a re aleer manaman dueta nanmarki kan, pwen sapwileda auer ta ieu ren man o.',
        13: 'Ir pukat kin wia insen ta ieu, o re pan ki ong man o ar manaman paki i ar angiangin o.',
        14: 'Ir pan mauini ong Sippul, a Sippul pan kaloe ir edi; pwe i ta Kaun en kaun akan o Nanmarki en nanmarki kan. O me iang i, me paeker, o pilier, o melel.',
        15: 'A masani ong ia: Pil oko, me koe kilanger, wasa me li sued o mondi ia, iei irail men liki, o kainok kan, o aramas akan, o lokaia kan.',
        16: 'O ose eisok, me koe kilanger, o man o, irail me pan tataki li sued o, o kasamaliala i, o kakilisauia ta, o re pan kangala uduk a, karongki i kisiniai.',
        17: 'Pwe Kot kotin kainongada mongiong ar, en wia kupur a, o en wia lamalam ta pot o en upai man o, a lao masan en Kot pwaida.',
        18: 'Li o, me koe kilanger, iei kanim lapalap, me kakaun nanmarki kan nan sappa.',
    },
    18: {
        1: 'MURIN mepukat i kilanger amen tounlang kodido sang lang, me manaman kaualap, o sappa marain kila a lingan.',
        2: 'A kotin molipeki kapitie laud masani: A rongk pasang, o rongk pasang, Papilon lapalap, ap id wiala deun tewil akan, o deun ngen saut karos, o deun manpir samin, o katantat.',
        3: 'Pwe wei karos nim sang wain makar en a nenek, o nanmarki en sappa neneker re a, o saunet en sappa kapwapwakier a kapwa kasampwal akan.',
        4: 'O i ronger eu ngil sang lang masani: Ko wei sang i nai aramas akan, pwe komail der ainekida dip ar kan, pwe komail der pukoki kompar akan.',
        5: 'Pwe dip a kan lel onger lang, o Kot kotin tamanda a sued akan.',
        6: 'Depuk ong i, duen pein i wiadar! O depuk ong i pan riapak, duen a mau ong a wiawia kan; dal o, me a audedar, i dal ota komail aude ong i pan riapak!',
        7: 'Duen a kin kalinganda pein i, o kamuei matier, iei due ki ong i kalokepa o kasonglolpa, pwe a mongeloleki: Ngai nanmarki li amen, o i so pan li odi, o i sota pan kilang mesued kot.',
        8: 'I me kompa kan pan lel ong i ni rang ota: Mela, o maiei, o lek, o a pan rong kila kisiniai, pwe Kaun Kot me manaman, me kadeikada i;',
        9: 'O nanmarki en sappa kan, me nenek re a, o muei mat sang i, re pan maieiki, o weriwereki i ni ar kilang adiniai en a rongala.',
        10: 'O re pan u wasa doo waponki a kamekam indada: Apwal, apwal Papilon, kanim lapalap, Papilon kanim kelail! Ni aur ta ieu kadeik paom pwaida.',
        11: 'O saunet en sappa kan maiei o sangesangki i, pwe sota amen me neti ar kapwa kan.',
        12: 'Kapwa kold, o silper, o takai kasampwal akan, o manaman akan, o likau linen kaselel, o likau tol, o likau silk, o likau waitata, o song en tuka pomau karos, o song en dal karos, me wia kidar ngi en elepant, o dal akan, wia kidar tuka kasampwal, o mata pras, o mata, o marmor,',
        13: 'O simet, o potik, o men isis, o me pomau, o pomau en isis, o wain, o le, o plaua kasampwal, o wan wit, o man akan, o man sip, o os akan, o dake pan os, o ladu kan, o ngen en aramas akan,',
        14: 'O wan tuka kan, me kaped om kin iauki, rose sang uk er, o dipisou lingan o kaselel rose sang uk er, a solar pan diarokada kokolata.',
        15: 'Saunet en mepukat, me kapwapwadar re a, me pan u wasa doo, wapon kida a kamekam sangesang o mamaiei.',
        16: 'Indinda: Apwal, apwal kanim lapalap, me kapwadeki likau ankotitik, o tol, o waitata, o kapwadeki kold, o takai kasampwal, o manaman!',
        17: 'Pwe ni auer ta ieu kapwa toto pukat olar. O saupal en sop, o ir, me toun sop, o seler akan, o saunet en nan madau, ir uda wasa doo.',
        18: 'O weriwereda, ni ar kilanger adiniai en a isis, indinda: Ia kanim, me rasong kanim lapalap wet!',
        19: 'Irail tukatuk en mong wereda, sangesang, mamaiei, indinda: Apwal apwal kanim lapalap! Tou a, me ar sop akan mi nan madau, kapwapwalar, pwe a neti re a mulatokia. Ni auer ta ieu a mokonaidier.',
        20: 'Kaneketeki i lang, o saraui kan, o wanporon kan, o saukop akan, pwe Kot me kotin iki ong i komail.',
        21: 'Tounlang roson amen pokada takai due takai lap men iris plaua, ap kasedi ong madau, masani: Iduen Papilon kanim lap pan karongk pasang, ap pan solar mia.',
        22: 'Ngil en me wia arp akan o kakaul akan, o me peuk kasang plöte, o me peuk koronete, pan solar me pan rong re a, o solar saupal, me pan diarok lol om, o ngirsok en takai iris plaua solar me pan rong lol om.',
        23: 'O marain en lamp pan solar senser lol om, o ngil en ol kamod o li kamod solar me pan rong lol om, pwe noum saunet akan, saumas en sappa, kainok karos pakotaue kilar om widing kan.',
        24: 'O ntan saukop o saraui kan me diarokadar lol om, o ntan karos, me kamekamelar sappa.',
    },
    19: {
        1: 'MURIN mepukat i ronger likamada morong en pokon kalaimun nanlang, masani: Aleluia, kamaur, o lingan, o manaman udan atail Kot!',
        2: 'Pwe melel o me pung ar kadeik kan; pwe a kotin kadeikadar li sued lapalap, me kasuedie kilar toun sappa a nenek kan o a ikier ntan na ladu kan.',
        3: 'Pil kariapak re inda: Aleluia! A adiniai adidala kokolata.',
        4: 'O lapalap riekpamen o man pamen rap poridi pongi ong Kot, me kaipokedi pon mol a, masani: Amen Aleluia!',
        5: 'O ngil, me peido sang mol o masani: Kapinga atail Kot, komail sapwilim a ladu kan, komail, me lan i, me tikitik o me lapalap akan!',
        6: 'O i ronger morong en pokon kalaimun, o due ngil en pil toto, o due ngiringir en nansapwe kan indinda: Aleluia, pwe Kaun atail Kot, me Kaun en meakaros a wialar Nanmarki.',
        7: 'Kitail en insenemau, o pereperen, o wauneki i, pwe a leler en Sippul a kapapaud, o li kamod onopadar.',
        8: 'O a muei ong i, en likauwia kida likau linen, me min o makelekel; pwe likau linen makelekel iei kadeik pung en me wiaui pweki saraui kan.',
        9: 'A masani ong ia: Intingiedi: Re meid pai, me luke dong kamadip en kapapaud en Sippul o. O a masani ong ia: Mepukat masan melel akan en Kot.',
        10: 'I ap pupedi ni aluwilu a, en pongi i. A masani ong ia: Koe der, ngai sau om, o ri om, me aneki kadede pan Iesus; pongi Kot. A ngen en kokop iei kadede pan Iesus.',
        11: 'O i kilanger lang a ritidar o os puetepuet amen, o me kaipokedi poa, me oroneki Pung o Melel; a kadeikada o mauinda ni me pung.',
        12: 'Por en silang i me rasong umpul en kisiniai, o mar a toto mia ni tapwi, a mar eu intingidier, me sota amen me asa, pein i ta.',
        13: 'A likau kida likau eu, me kadueki nta, o mar a oroneki: Masan en Kot.',
        14: 'O karis en saunpei en nanlang idauen i pon os puetepuet akan, likau kida linen puetepuet o min.',
        15: 'O sang nan silang i kodlas kong lus da sang, men kamekameki wein sappa. A pan kotin kaun kida sokon mata pot; o a tiakedi kopa en wain, me ongiong en Kot, Kaun en meakaros.',
        16: 'Ni a likau o ni langelange a mar a intingidier: Nanmarki en nanmarki o Kaun en kaun akan.',
        17: 'O i kilanger tounlang amen uda nan katipin; a molipeiki ngil laud masani ong manpir akan, me pipir nan warong en lang: Kodo, pokon dong kamadip lapalap en Kot.',
        18: 'Pwe komail en kang uduk en nanmarki kan, o uduk en kaun akan, o uduk en manaman akan, o uduk en os akan, o me mondi po arail, o uduk en me maio ko o ladu kan, me tikitik o me lapalap akan.',
        19: 'O i kilanger man o, o nanmarki en sappa kan, o nair karis akan pokon penang mauini ong i, me kaipokedi pon os o na karis akan.',
        20: 'Man o lodi ong iangaki saukop likam, me wia kilel kai mo a, me a kotaue kida irail, me kilele kidi kilel en man o, o ir me pongi a kilel. Ira karos lokidokilang nan le en kisiniai, me rongerongki swepel ni ara memaur.',
        21: 'Me lu akan kamekame kila kodlas en i, me kaipokedi pon os o, iei kodlas, me lusa sang nan silang i; ari manpir akan muei mat kilar uduk arail.',
    },
    20: {
        1: 'I kilanger tounlang amen kotido sang lang, ki en wasa lol mi re a nan lim a o sal mata lapalap.',
        2: 'A saikidi drake o serpent en kaua, iei Tewil o Satan, ap saliedi i par kid.',
        3: 'O kasedi ong nan wasa lol so kapi, ritingiedi o kileledi poa, pwe ender katikatiamau toun sappa, a lao par kid imwisokala. Muri a nok sapadokala ansau kis.',
        4: 'O i kilanger mol akan, o ir me kaipokedi poa, kadeikada; o i kilanger ngen en ir, me mong ar lepuki sanger pweki kadedepan Iesus o masan en Kot, o ir, me so pongi man o, o a kilel, o so kilelekida a kilel ni tam ar o ni pa ar. Irail mauredar ap iang Kristus kakaun par kid.',
        5: 'A me melar tei kan sota maureda lao par kid imwisokala, iei iasada kaieu.',
        6: 'A meid pai o saraui, me pan konodi ias kaieu; mela kariau so kokoa irail, pwe irail wiala samero en Kot o en Kristus akan, o re pan iang i kakaun par kid.',
        7: 'Par kid lao imwisokela, Satan ap pan sapedokla sang a im en kateng.',
        8: 'A ap pan parwei katikatiamau toun sap akan, me mi ni kaim paieu en sappa, Kok o Makok, kapokon ir penang mauin; ir me ngederenia rasong pik en oror.',
        9: 'Irail paraparalang nan sappa, rap kapil pena pokon en saraui kan, o kanim kapai; kisiniai ap moredi sang lang, karong ir ala.',
        10: 'O tewil, me kotaue ir, lokidokila nan le en kisiniai o swepel, wasa me man o saukop likam mia ia, o re pan kalokolok ni ran o ni pong kokolata soutuk.',
        11: 'O i kilanger mol puetepuet lapalap eu, o i me kaipokedi poa sappa o lang tang wei sang mon silang i, ap solar deu ara me diarokadar.',
        12: 'O i kilanger melar akan tikitik o lapalap akan u mon mol o, o puk kan pak pasanger, o pil eu puk me pak pasanger, me puk en kamaur. Melar akan ap pakadeik kidar meakan, me intingkier nan puk kan duen ar wiawia kan.',
        13: 'O madau kapeida melar akan, me mimi lole, o mela o wasan mela kidaer, me mi lol ir. Ir karos pakadeikadar iran ar wiawia kan.',
        14: 'Mela o wasan mela me pisikindi lang le en kisiniai; iei mela kariau.',
        15: 'O meamen, me so intingidier nan puk en kamaur, a pisikindi lang le en kisiniai.',
    },
    21: {
        1: 'O I kilanger lang kap o sappa kap, pwe lang mas o sappa mas solar mia, o solar madau.',
        2: 'O i kilanger kanim isou, Ierusalem kap, peidido sang lang ren Kot, kapwater due li kamod kapwater ong a paud ol.',
        3: 'O i ronger ngil laud sang mol o masani: Kilang, tanpas en Kot mi ren aramas akan, o a pan kotikot re’rail, o irail pan wia sapwilim a aramas ala, o pein Kot pan kotikot re’rail.',
        4: 'O a pan kotin limwi sang pil en mas ar karos; o mela pan solar, pil solar maiei, o solar sangesang, madak kokolata, pwe men mas solar mia.',
        5: 'O me kaipokedi pon mol o masani: Kilang, I pan kawilikapada meakan karos. O a kotin masani: Intingiedi; pwe masan pukat me pung o melel!',
        6: 'A kotin masani ong ia: A pwaidar. Ngai Alpa o Omeka, Tapi o Imwi. I pan ki ong, me men nim pil adar, en nim sang utun pil en maur sapan.',
        7: 'Me pan dadaurata, a pan sosoki mepukat, o I pan wia na Kot la, o a pan wiala nai seri.',
        8: 'A me masak, o sokamelele, o saut akan o men kamela kan, o nenek kan, o wun ani kan, o me pongi dikedik en ani kan, o likam kan karos deu ar nan le, me rongerongki kisiniai o swepel, iei mela kariau.',
        9: 'O tounlang amen, kisan isimen, me dal en kalokolok isu en kaimwisokela mi re a, pwarado masani ong ia: Ko dong met, i pan kasale ong uk li kamod, warok en Sippul o.',
        10: 'Ari a kotin kalua kin ia la ren ngen pon nana lapalap eu o ileile, ap kasale ong ia kanim isou Ierusalem, peipeidido sang lang ren Kot;',
        11: 'Linganeki lingan en Kot; a marain me rasong takai kasampwal, rasong iaspis lingan eu,',
        12: 'A kel lapalap ileile mia, o wanim eisokriau, o tounlang ekriamen mi ni wanim ko, o mar akan intingidier, me mar en nain Israel ekriamen.',
        13: 'Ni mas en lang wanim silu, o ni apong wanim silu, o ni air wanim silu, o ni kapi wanim silu.',
        14: 'Pason en kel en kanim o me eisokriau, o mar en wanporon en Sippul o ekriamen intingidier po ar.',
        15: 'Me masani ong ia mepukat, men song sokon kold mi re a, pwen song kanim o, o a wanim akan o a kel o.',
        16: 'Pali en kanim pali paieu, o anget a dueta tälap a; a songki kanim men song o, me anget a stadien nenriakid. Anget a o tälap o ileile duepeneta.',
        17: 'A sosong kel o, ari me tipong en pa epuki paeisok paieu, duen men song en aramas o, me mi ren tounlang o.',
        18: 'A kel o wia kidar iaspis, a kanim o wia kidar kold eta, me rasong klas makelekel.',
        19: 'Pason en kel en kanim o usunakier song en takai kasampwalia karos. Tapin pason takai iaspis, a kariau sapir, a kasilu kalsedonia, a kapaieu smarakd,',
        20: 'A kalimau sardoniks, a kawonu sardis, a kaisu krisolit, a kawalu peril, a katuau topas, a kaeisok krisopras, a kaeisokeu iasint, a kaeisokriau ametist.',
        21: 'O wanim eisokriau manaman eisokriau; ari, wanim eu iei manaman eu; o al en kanim o me kold makelekel, lingan due klas.',
        22: 'O i sota kilanger im en kaudok lole, pwe Kaun Kot, Kaun en meakaros o Sippul iei ar im en kaudok.',
        23: 'O kanim sota mau ong katipin de maram, pwen dakedaker, pwe lingan en Kot kamaraini i, o Sippul iei arail lamp.',
        24: 'O wei kan pan weid wei ni a lingan; o nanmarki en sappa kan pan walang i ar lingan.',
        25: 'O a wanim akan sota pan ritidi ni ran, pwe solar pong wasa o.',
        26: 'O irail pan wa dong i lingan o wau en wei kan,',
        27: 'Sota me pan pedelong ong me samin, de me kin wia saut, de likam, a irail eta, me mar arail intingidier nan puk en maur en Sippul.',
    },
    22: {
        1: 'O A kotin kasale ong ia pilap en kamaur pot, makelekel due kristal, me u wei sang ni mol en Kot o Sippul.',
        2: 'Ni kailan pilap pali karos tukan kamaur mia, me kin wa song en wa eisokriau, me wa saunipong kaukaule; o tan tuka kan men kamaur toun sappa.',
        3: 'O solar men kariala kokolata; a mol en Kot o Sippul me mi lole; o sapwilim a ladu kan pan upa i,',
        4: 'O re pan kilang silang i, o mar a pan mi ni tam ar.',
        5: 'O solar pong ni wasa o kokolata; re solar anane marain en lamp, pil solar marain en katipin, pwe Kaun Kot pan kotin kamaraini ir, o re pan nanmarki kokolata.',
        6: 'A masani ong ia: Masan me pung o melel, o Kaun Kot en ngen en saukop akan poronedo sapwilim a tounlang, en kasale ong sapwilim a ladu kan, me pan wiaui ni ansau koren.',
        7: 'Kilang, I pan madang pwarado, meid pai, me kanekid masan akan en kokop en puk wet!',
        8: 'Ngai Ioanes, me ronger o kilanger mepukat, o ni ai ronger o kilanger, i ap poridier pongi mon aluwilu en tounlang, me kasale ong ia mepukat.',
        9: 'O a masani ong ia: Koe der, ngai pil iang uk papa amen o iang ri om saukop akan, o iang ir, me kanekid masan en puk wet, pongi Kot!',
        10: 'O a masani ong ia: Koe der katenge masan en kokop en puk wet, pwe ansau o korendor.',
        11: 'Me so pung, en sapesapungeta, o me samin, en samisamineta, o me pung, en pungepungeta, o me saraui en saraui ta.',
        12: 'Kilang, i madang pwarado o ai pwain mi re i, en pwain ong amen amen duen ar wiawia kan.',
        13: 'Ngai Alpa o Omeka, men Mas o Men mur, Tapi o Imwi.',
        14: 'Re meid pai, me lope ar likau, pwe ren kon ong tuka en kamaur, o pedelong ong nan wanim en kanim akan!',
        15: 'Liki kiti kan mia, o widingok kan, o nenek kan, o kamela kan, o me pongi dikedik en ani, o amen amen me mauki o me wiada likam.',
        16: 'Ngai Iesus kadar doer nai tounlang, en kadede ong komail mepukat, mon momodisou kan. Ngai tapin kadaudok en Dawid, usu ran umpumpul.',
        17: 'Ngen o li kamod masani: Kodo! O me pan rong, en inda: Kodo! O me men nim, en kodo, meamen me inong iong, en tungole pil en kamaur sapan.',
        18: 'I kadede ong amen amen me rong masan en kokop en puk wet, ma amen pan usai ong, Kot pan kotiki ong i kampa kan, me intingidier nan puk wet.',
        19: 'O ma amen pan kase song ekis masan en kokop wet, Kot pan kotiki sang pwais a nin tukan kamaur o kanim isou, me intingidier nan puk wet.',
        20: 'Me kin kadede mepukat, masanier: Iei I pan madang pwarado. Amen, kotido Maing Iesus!',
        21: 'Mak en Kaun Iesus Kristus en mi ren saraui kan karos! Amen.',
    },
}
